SELECT * FROM integration.get_transaction_updates('0001-01-01 00:00:00.000000'::timestamp, '9999-12-31 23:59:59.999999'::timestamp);
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['Date Key', 'WWI Customer Transaction ID', 'WWI Supplier Transaction ID', 'WWI Invoice ID', 'WWI Purchase Order ID', 'Supplier Invoice Number', 'Total Excluding Tax', 'Tax Amount', 'Total Including Tax', 'Outstanding Balance', 'Is Finalized', 'WWI Customer ID', 'WWI Bill To Customer ID', 'WWI Supplier ID', 'WWI Transaction Type ID', 'WWI Payment Method ID', 'Last Modified When']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 06 [A06 window at the extremes of datetime2 and transaction dates 1753-01-01 and 9999-12-31 on both halv…', got, ARRAY['Date Key', 'WWI Customer Transaction ID', 'WWI Supplier Transaction ID', 'WWI Invoice ID', 'WWI Purchase Order ID', 'Supplier Invoice Number', 'Total Excluding Tax', 'Tax Amount', 'Total Including Tax', 'Outstanding Balance', 'Is Finalized', 'WWI Customer ID', 'WWI Bill To Customer ID', 'WWI Supplier ID', 'WWI Transaction Type ID', 'WWI Payment Method ID', 'Last Modified When']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('9999-12-31', '2', NULL, NULL, NULL, NULL, '100', '15', '115', '0', '1', '5', '5', NULL, '1', NULL, '9999-12-31 23:59:59.999999'),
  ('1753-01-01', '3', NULL, NULL, NULL, NULL, '100', '15', '115', '0', '1', '5', '5', NULL, '1', NULL, '0001-01-01 00:00:00.000001'),
  ('1753-01-01', NULL, '1', NULL, NULL, 'INV-1', '-50', '-7.5', '-57.5', '0', '0', NULL, NULL, '4', '5', '2', '0001-01-01 00:00:00.000001'),
  ('9999-12-31', NULL, '3', NULL, NULL, 'INV-3', '-50', '-7.5', '-57.5', '0', '0', NULL, NULL, '4', '5', '2', '9999-12-31 23:59:59.999999');
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 06 [A06 window at the extremes of datetime2 and transaction dates 1753-01-01 and 9999-12-31 on both halv…', missing, extra;
  END IF;
END $pp$;
ROLLBACK;
